{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Konklusionen er korrekt: arbejdsophør giver ikke i sig selv ret til tillægget. Udbetaling Danmark ser på arbejdets karakter i forhold til funktionsnedsættelsen og vurderer, om andre typer arbejde er muligt, eventuelt med skånehensyn eller i mindre omfang. Svaret gør ikke ophør automatisk afgørende og begrænser ikke vurderingen til det tidligere arbejde. Formuleringen om 'stort set ikke muligt ... i nævneværdigt omfang' er en skærpet glose, men ændrer ikke den juridiske hovedkonklusion."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med. Arbejdets karakter sammenholdes med funktionsnedsættelsen. Muligheden for andre typer arbejde vurderes, og svaret nævner lægefaglige oplysninger og aktuelle symptomer. Skånehensyn og mindre omfang indgår udtrykkeligt. Arbejde uden fysisk belastning nævnes som eksempel."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: om arbejdsophør i sig selv giver ret, og hvad Udbetaling Danmark vurderer. Tilbuddet om en klientmail er blot en tilføjelse."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver identificerbare kilder: Vejledning nr. 10157 og SU-bekendtgørelsen nr. 841. De lægger sig op ad konkrete udsagn via henvisningsmarkører, og kilderne er selv identificerbare."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning 10157 og SU-bekendtgørelsen nr. 841 er autoritative og aktuelle inden for den frosne afgrænsning. Vejledningen svarer til den officielle passage om arbejdsophør (afsnit 3.4.1.3), og bekendtgørelsen svarer til de formelle bestemmelser."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Kernepåstandene om arbejdets karakter, andre typer arbejde, skånehensyn og positivlisten er understøttet. Flere væsentlige påstande er det ikke. 'Stort set ikke muligt at påtage sig erhvervsarbejde i nævneværdigt omfang' står ikke i de viste passager eller bestemmelser. Det samme gælder, at ophøret er 'et stærkt argument', og at Udbetaling Danmark skal tjekke, om ophøret 'faktisk skyldes funktionsnedsættelsen og ikke andre forhold'. Kildehenvisningerne er desuden uspecifikke tal."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en tærskelformulering uden støtte i materialet: 'stort set ikke er muligt ... i nævneværdigt omfang'. Loven siger 'meget betydelige begrænsninger'. Svaret tilføjer også en kausalitetsprøvelse af, om ophøret 'ikke skyldes andre forhold', mens vejledningen siger 'efter det oplyste'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "De påkrævede forbehold er bevaret. Arbejdsophør er et relevant moment og udgangspunkt for en nærmere vurdering, men ikke automatisk afgørende. Ikke-fysisk belastende arbejde fremstår som et eksempel og ikke som en selvstændig betingelse. Skånehensyn og mindre omfang er med."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Argumentationen er sammenhængende: ophør er relevant, men ikke tilstrækkeligt, derfor kræves en konkret vurdering af arbejdsevnen, og konklusionen følger heraf."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Modaliteterne er overvejende præcise. 'Skal stadig vurdere', 'vil typisk spørge' og 'ikke en automatisk adgangsbillet' gengiver vejledningens vurderingsmæssige karakter uden at gøre skøn absolutte. Ikke-fysisk belastende arbejde fremstilles ikke som et krav."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "yes",
      "reason": "Svaret dækker situationen, hvor ansøgeren oplyser at være ophørt i arbejdet på grund af funktionsnedsættelsen. Udbetaling Danmark ser på arbejdets karakter i forhold til funktionsnedsættelsen."
    },
    "A23": {
      "label": "yes",
      "reason": "Svaret angiver, at Udbetaling Danmark vurderer, om ansøgeren kan varetage andet arbejde, eventuelt med skånehensyn eller i mindre omfang. Det nævner også arbejde, der ikke er fysisk belastende."
    }
  },
  "overall_notes": "Svaret er indholdsmæssigt korrekt og dækker de kritiske elementer og forbeholdene. Svagheden er, at det tilføjer en skærpet tærskelformulering ('stort set ikke muligt ... nævneværdigt omfang'), en kausalitetsprøvelse og karakteristikken 'stærkt argument' uden støtte i de frosne kilder. Kildehenvisningerne er desuden uspecifikke. Derfor er C06 og C07 not_met."
}

